func (q *Queries) ListTitlesByIDs(ctx context.Context, ids []int64) ([]Title, error) {
	query := listTitlesByIDs
	var queryParams []interface{}
	if len(ids) > 0 {
		for _, v := range ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Title{}
	for rows.Next() {
		var i Title
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Name,
			&i.Kind,
			&i.TmdbID,
			&i.LegacyImdbID,
			&i.LegacyRtUrl,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.MatchStatus,
			&i.MatchSource,
			&i.MatchedName,
			&i.MatchedYear,
			&i.MatchAttempts,
			&i.MatchAttemptedAt,
			&i.NextMatchAt,
			&i.LegacyRtAttempts,
			&i.LegacyNextRtAt,
			&i.LegacyJustwatchID,
			&i.LegacyWikidataID,
			&i.FpName,
			&i.FpKind,
			&i.FpPremiereDate,
			&i.FpCountry,
			&i.FpFetchedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listTitlesDueForMatch = `-- name: ListTitlesDueForMatch :many
SELECT t.id, t.slug, t.name, t.kind, t.tmdb_id, t.legacy_imdb_id, t.legacy_rt_url, t.created_at, t.updated_at, t.match_status, t.match_source, t.matched_name, t.matched_year, t.match_attempts, t.match_attempted_at, t.next_match_at, t.legacy_rt_attempts, t.legacy_next_rt_at, t.legacy_justwatch_id, t.legacy_wikidata_id, t.fp_name, t.fp_kind, t.fp_premiere_date, t.fp_country, t.fp_fetched_at
FROM titles t
WHERE t.match_status IN ('pending', 'unmatched')
  AND (t.next_match_at IS NULL OR t.next_match_at <= CURRENT_TIMESTAMP)
ORDER BY CASE WHEN t.match_status = 'pending' THEN 0 ELSE 1 END,
         (SELECT MAX(r.ranked_on) FROM rankings r WHERE r.title_id = t.id) DESC,
         t.id DESC
LIMIT ?1
`

// Unmatched titles whose backoff has expired, never-tried first, then the
// most recently charting.
func (q *Queries) ListTitlesDueForMatch(ctx context.Context, limit int64) ([]Title, error) {
	rows, err := q.db.QueryContext(ctx, listTitlesDueForMatch, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Title{}
	for rows.Next() {
		var i Title
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Name,
			&i.Kind,
			&i.TmdbID,
			&i.LegacyImdbID,
			&i.LegacyRtUrl,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.MatchStatus,
			&i.MatchSource,
			&i.MatchedName,
			&i.MatchedYear,
			&i.MatchAttempts,
			&i.MatchAttemptedAt,
			&i.NextMatchAt,
			&i.LegacyRtAttempts,
			&i.LegacyNextRtAt,
			&i.LegacyJustwatchID,
			&i.LegacyWikidataID,
			&i.FpName,
			&i.FpKind,
			&i.FpPremiereDate,
			&i.FpCountry,
			&i.FpFetchedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listTmdbRefsChartingSince = `-- name: ListTmdbRefsChartingSince :many
SELECT CASE t.kind WHEN 'tv_show' THEN 'tv' ELSE 'movie' END AS tmdb_kind,
       CAST(t.tmdb_id AS TEXT) AS tmdb_id,
       CAST(MAX(r.ranked_on) AS TEXT) AS last_ranked_on
FROM rankings r
JOIN titles t ON t.id = r.title_id
WHERE r.ranked_on >= CAST(?1 AS TEXT)
  AND COALESCE(t.tmdb_id, '') <> ''
GROUP BY t.kind, t.tmdb_id
ORDER BY MAX(r.ranked_on) DESC, MIN(r.rank) ASC
LIMIT ?2
`

type ListTmdbRefsChartingSinceParams struct {
	Since string `json:"since"`
	Limit int64  `json:"limit"`
}

type ListTmdbRefsChartingSinceRow struct {
	TmdbKind     string `json:"tmdb_kind"`
	TmdbID       string `json:"tmdb_id"`
	LastRankedOn string `json:"last_ranked_on"`
}

// Matched titles on any chart since a date (YYYY-MM-DD), most recent first.
func (q *Queries) ListTmdbRefsChartingSince(ctx context.Context, arg ListTmdbRefsChartingSinceParams) ([]ListTmdbRefsChartingSinceRow, error) {
	rows, err := q.db.QueryContext(ctx, listTmdbRefsChartingSince, arg.Since, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTmdbRefsChartingSinceRow{}
	for rows.Next() {
		var i ListTmdbRefsChartingSinceRow
		if err := rows.Scan(&i.TmdbKind, &i.TmdbID, &i.LastRankedOn); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const rankingStats = `-- name: RankingStats :one
SELECT COUNT(*) AS rankings, CAST(COALESCE(MAX(ranked_on), '') AS TEXT) AS latest_ranked_on
FROM rankings
`

type RankingStatsRow struct {
	Rankings       int64  `json:"rankings"`
	LatestRankedOn string `json:"latest_ranked_on"`
}

func (q *Queries) RankingStats(ctx context.Context) (RankingStatsRow, error) {
	row := q.db.QueryRowContext(ctx, rankingStats)
	var i RankingStatsRow
	err := row.Scan(&i.Rankings, &i.LatestRankedOn)
	return i, err
}

const recordTitleMatchAttempt = `-- name: RecordTitleMatchAttempt :one
UPDATE titles
SET match_status       = CASE WHEN CAST(?1 AS INTEGER) = 1 THEN match_status ELSE 'unmatched' END,
    matched_name       = CASE WHEN CAST(?1 AS INTEGER) = 1 THEN ?2 ELSE matched_name END,
    matched_year       = CASE WHEN CAST(?1 AS INTEGER) = 1 THEN ?3 ELSE matched_year END,
    match_attempts     = match_attempts + 1,
    match_attempted_at = CURRENT_TIMESTAMP,
    next_match_at      = CASE WHEN CAST(?4 AS TEXT) = '' THEN NULL
                              ELSE datetime('now', CAST(?4 AS TEXT)) END,
    updated_at         = CURRENT_TIMESTAMP
WHERE id = ?5 AND match_status <> 'manual'
RETURNING id, slug, name, kind, tmdb_id, legacy_imdb_id, legacy_rt_url, created_at, updated_at, match_status, match_source, matched_name, matched_year, match_attempts, match_attempted_at, next_match_at, legacy_rt_attempts, legacy_next_rt_at, legacy_justwatch_id, legacy_wikidata_id, fp_name, fp_kind, fp_premiere_date, fp_country, fp_fetched_at
`

type RecordTitleMatchAttemptParams struct {
	Found       int64          `json:"found"`
	MatchedName sql.NullString `json:"matched_name"`
	MatchedYear sql.NullInt64  `json:"matched_year"`
	RetryAfter  string         `json:"retry_after"`
	ID          int64          `json:"id"`
}

// One automatic matching attempt (what it found is mapping evidence): a
// title without a result is unmatched until retry_after (a SQLite datetime
// modifier). Never touches a title fixed by hand.
func (q *Queries) RecordTitleMatchAttempt(ctx context.Context, arg RecordTitleMatchAttemptParams) (Title, error) {
	row := q.db.QueryRowContext(ctx, recordTitleMatchAttempt,
		arg.Found,
		arg.MatchedName,
		arg.MatchedYear,
		arg.RetryAfter,
		arg.ID,
	)
	var i Title
	err := row.Scan(
		&i.ID,
		&i.Slug,
		&i.Name,
		&i.Kind,
		&i.TmdbID,
		&i.LegacyImdbID,
		&i.LegacyRtUrl,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.MatchStatus,
		&i.MatchSource,
		&i.MatchedName,
		&i.MatchedYear,
		&i.MatchAttempts,
		&i.MatchAttemptedAt,
		&i.NextMatchAt,
		&i.LegacyRtAttempts,
		&i.LegacyNextRtAt,
		&i.LegacyJustwatchID,
		&i.LegacyWikidataID,
		&i.FpName,
		&i.FpKind,
		&i.FpPremiereDate,
		&i.FpCountry,
		&i.FpFetchedAt,
	)
	return i, err
}

const requeueTitleMatch = `-- name: RequeueTitleMatch :exec
UPDATE titles
SET next_match_at  = NULL,
    match_attempts = CASE WHEN CAST(?1 AS INTEGER) = 1 THEN 0 ELSE match_attempts END,
    matched_name   = CASE WHEN CAST(?1 AS INTEGER) = 1 THEN NULL ELSE matched_name END,
    matched_year   = CASE WHEN CAST(?1 AS INTEGER) = 1 THEN NULL ELSE matched_year END,
    updated_at     = CURRENT_TIMESTAMP
WHERE id = ?2
`

type RequeueTitleMatchParams struct {
	Clear int64 `json:"clear"`
	ID    int64 `json:"id"`
}

// Due for matching now; clear also forgets the attempts and matched name.
func (q *Queries) RequeueTitleMatch(ctx context.Context, arg RequeueTitleMatchParams) error {
	_, err := q.db.ExecContext(ctx, requeueTitleMatch, arg.Clear, arg.ID)
	return err
}

