const titleMappingStats = `-- name: TitleMappingStats :one
SELECT
    COUNT(*) AS total,
    CAST(COALESCE(SUM(CASE WHEN COALESCE(t.tmdb_id, '') = '' THEN 1 ELSE 0 END), 0) AS INTEGER) AS missing_tmdb,
    CAST(COALESCE(SUM(CASE WHEN COALESCE(m.imdb_id, '') = '' THEN 1 ELSE 0 END), 0) AS INTEGER) AS missing_imdb,
    CAST(COALESCE(SUM(CASE WHEN COALESCE(m.rt_id, '') = '' THEN 1 ELSE 0 END), 0) AS INTEGER) AS missing_rt
FROM titles t
LEFT JOIN tmdb_titles m ON m.tmdb_kind = CASE t.kind WHEN 'tv_show' THEN 'tv' ELSE 'movie' END AND m.tmdb_id = t.tmdb_id
`

type TitleMappingStatsRow struct {
	Total       int64 `json:"total"`
	MissingTmdb int64 `json:"missing_tmdb"`
	MissingImdb int64 `json:"missing_imdb"`
	MissingRt   int64 `json:"missing_rt"`
}

func (q *Queries) TitleMappingStats(ctx context.Context) (TitleMappingStatsRow, error) {
	row := q.db.QueryRowContext(ctx, titleMappingStats)
	var i TitleMappingStatsRow
	err := row.Scan(
		&i.Total,
		&i.MissingTmdb,
		&i.MissingImdb,
		&i.MissingRt,
	)
	return i, err
}

const upsertChartSnapshot = `-- name: UpsertChartSnapshot :exec
INSERT INTO chart_snapshots (ranked_on, country, streaming_provider, category, entry_count, signature, source, run_id)
VALUES (?1, ?2, ?3, ?4,
        ?5, ?6, ?7, ?8)
ON CONFLICT(ranked_on, country, streaming_provider, category) DO UPDATE SET
    entry_count = excluded.entry_count,
    changed_at  = CASE WHEN chart_snapshots.signature = excluded.signature THEN chart_snapshots.changed_at ELSE CURRENT_TIMESTAMP END,
    signature   = excluded.signature,
    source      = excluded.source,
    run_id      = excluded.run_id,
    scraped_at  = CURRENT_TIMESTAMP
`

type UpsertChartSnapshotParams struct {
	RankedOn          string        `json:"ranked_on"`
	Country           string        `json:"country"`
	StreamingProvider string        `json:"streaming_provider"`
	Category          string        `json:"category"`
	EntryCount        int64         `json:"entry_count"`
	Signature         string        `json:"signature"`
	Source            string        `json:"source"`
	RunID             sql.NullInt64 `json:"run_id"`
}

func (q *Queries) UpsertChartSnapshot(ctx context.Context, arg UpsertChartSnapshotParams) error {
	_, err := q.db.ExecContext(ctx, upsertChartSnapshot,
		arg.RankedOn,
		arg.Country,
		arg.StreamingProvider,
		arg.Category,
		arg.EntryCount,
		arg.Signature,
		arg.Source,
		arg.RunID,
	)
	return err
}
